import test from'node:test';import assert from'node:assert/strict';import{readFileSync}from'node:fs';import{verifyMobileKeyboardIconFitRelease}from'./check-mobile-keyboard-icon-fit-release-20261101.mjs';
void test('the 44px icon faces fit their original compact controls',()=>assert.equal(verifyMobileKeyboardIconFitRelease().approvedBy,'Nico'));
for(const[file,edit]of[['app/learner-layout.css',s=>s+'\n.cp-view-toggle{padding:8px}'],['docs/mobile-keyboard-icon-fit-20261101/checks.json',s=>s.replace('"allControlsFullyVisible": true','"allControlsFullyVisible": false')],['docs/mobile-keyboard-icon-fit-20261101/backup.json',s=>s.replace('"fullReadback": true','"fullReadback": false')]])void test('rejects altered '+file,()=>assert.throws(()=>verifyMobileKeyboardIconFitRelease(f=>f===file?Buffer.from(edit(readFileSync(f).toString())):readFileSync(f))));
